import Foundation
import Network
import Observation

/// Bonjour discovery of robot daemons.
///
/// Watches both service types the daemon advertises: `_reachy-mini._tcp`
/// (primary) and `_http._tcp` (legacy, instance names containing "reachy").
/// A browser stuck in `.waiting(kDNSServiceErr_PolicyDenied)` means the user
/// denied Local Network permission — discovery is otherwise silently empty.
@MainActor
@Observable
public final class RobotBrowser {
    public struct DiscoveredService: Identifiable, Hashable, Sendable {
        public var id: String {
            "\(type)/\(name)"
        }

        public let name: String
        public let type: String
        public let endpoint: NWEndpoint
    }

    public private(set) var servicesByType: [String: [DiscoveredService]] = [:]
    public private(set) var browserStates: [String: String] = [:]
    private var browsers: [NWBrowser] = []

    public nonisolated static let serviceTypes = ["_reachy-mini._tcp", "_http._tcp"]

    public init() {}

    public var services: [DiscoveredService] {
        servicesByType.values.flatMap(\.self).sorted { $0.id < $1.id }
    }

    public var permissionLooksDenied: Bool {
        browserStates.values.contains(where: Self.stateLooksPolicyDenied)
    }

    nonisolated static func stateLooksPolicyDenied(_ state: String) -> Bool {
        state.contains("PolicyDenied") || state.contains("-65570")
    }

    nonisolated static func acceptsService(name: String, type: String) -> Bool {
        !type.hasPrefix("_http") || name.localizedCaseInsensitiveContains("reachy")
    }

    public func start() {
        stop()
        for type in Self.serviceTypes {
            let browser = NWBrowser(for: .bonjour(type: type, domain: nil), using: .tcp)
            browser.stateUpdateHandler = { [weak self] state in
                Task { @MainActor in
                    self?.browserStates[type] = "\(state)"
                }
            }
            browser.browseResultsChangedHandler = { [weak self] results, _ in
                let found = results.compactMap { result -> DiscoveredService? in
                    guard case let .service(name, serviceType, _, _) = result.endpoint,
                          Self.acceptsService(name: name, type: serviceType)
                    else { return nil }
                    return DiscoveredService(name: name, type: serviceType, endpoint: result.endpoint)
                }
                Task { @MainActor in
                    self?.servicesByType[type] = found
                }
            }
            browser.start(queue: .main)
            browsers.append(browser)
        }
    }

    public func stop() {
        browsers.forEach { $0.cancel() }
        browsers = []
        servicesByType = [:]
        browserStates = [:]
    }
}

public enum BonjourResolver {
    /// Resolves a discovered Bonjour service to a concrete host:port by opening
    /// a throwaway TCP connection and reading the remote endpoint.
    public static func resolve(_ endpoint: NWEndpoint, timeout: Duration = .seconds(5)) async -> RobotAddress? {
        let connection = NWConnection(to: endpoint, using: .tcp)
        defer { connection.cancel() }
        return await withTaskGroup(of: RobotAddress?.self) { group in
            group.addTask {
                await withCheckedContinuation { continuation in
                    let resumed = Atomic(false)
                    connection.stateUpdateHandler = { state in
                        let finish: (RobotAddress?) -> Void = { address in
                            guard !resumed.swap(true) else { return }
                            continuation.resume(returning: address)
                        }
                        switch state {
                        case .ready:
                            if case let .hostPort(host, port) = connection.currentPath?.remoteEndpoint,
                               let host = Self.hostString(host)
                            {
                                finish(RobotAddress(host: host, port: Int(port.rawValue)))
                            } else {
                                finish(nil)
                            }
                        case .failed, .cancelled:
                            finish(nil)
                        default:
                            break
                        }
                    }
                    connection.start(queue: .global())
                }
            }
            group.addTask {
                try? await Task.sleep(for: timeout)
                return nil
            }
            let first = await group.next() ?? nil
            group.cancelAll()
            return first
        }
    }

    static func hostString(_ host: NWEndpoint.Host) -> String? {
        switch host {
        case let .ipv4(address):
            // NWEndpoint appends an interface zone ("%lo0") that is garbage in a URL.
            return stripZone("\(address)")
        case let .ipv6(address):
            let value = "\(address)"
            // A link-local address cannot be routed without its interface zone.
            guard !value.lowercased().hasPrefix("fe80:") || value.contains("%") else { return nil }
            return value.lowercased().hasPrefix("fe80:") ? value : stripZone(value)
        case let .name(name, _):
            return name
        @unknown default:
            return nil
        }
    }

    private static func stripZone(_ s: String) -> String {
        s.split(separator: "%").first.map(String.init) ?? s
    }
}

/// Tiny lock-protected flag for one-shot continuation resumption.
private final class Atomic: @unchecked Sendable {
    private var value: Bool
    private let lock = NSLock()

    init(_ value: Bool) {
        self.value = value
    }

    func swap(_ newValue: Bool) -> Bool {
        lock.lock()
        defer { lock.unlock() }
        let old = value
        value = newValue
        return old
    }
}

import Foundation
import OpenAPIRuntime
import OpenAPIURLSession

/// Owns the HTTP client for one robot daemon and performs the connection handshake.
///
/// The handshake establishes robot identity (hardware id, display name) and daemon
/// version before anything else — the version drives graceful degradation, and the
/// hardware id is the only safe way to deduplicate robots seen at several addresses.
public actor RobotConnection {
    public let address: RobotAddress
    private let client: Client

    public init(address: RobotAddress, session: URLSession? = nil) throws {
        guard let serverURL = address.rootURL else {
            throw ReachyKitError.invalidAddress(address)
        }
        self.address = address

        let resolvedSession: URLSession
        if let session {
            resolvedSession = session
        } else {
            let configuration = URLSessionConfiguration.ephemeral
            configuration.timeoutIntervalForRequest = 3.5
            resolvedSession = URLSession(configuration: configuration)
        }
        client = Client(
            serverURL: serverURL,
            transport: URLSessionTransport(configuration: .init(session: resolvedSession))
        )
    }

    /// Result of a successful handshake with the daemon.
    public struct Handshake: Sendable {
        public let identity: RobotIdentity
        public let status: Components.Schemas.DaemonStatus
        public let compatibility: DaemonCompatibility

        public init(
            identity: RobotIdentity,
            status: Components.Schemas.DaemonStatus,
            compatibility: DaemonCompatibility? = nil
        ) {
            self.identity = identity
            self.status = status
            self.compatibility = compatibility ?? DaemonCompatibilityPolicy.evaluate(identity.daemonVersion)
        }
    }

    public func handshake() async throws -> Handshake {
        let status = try await client.getDaemonStatusApiDaemonStatusGet().ok.body.json
        let compatibility = DaemonCompatibilityPolicy.evaluate(status.version)
        if case let .unsupported(reported, minimum) = compatibility {
            throw ReachyKitError.unsupportedDaemonVersion(reported: reported, minimum: minimum)
        }

        // hardware-id returns a string map (component serials); flatten deterministically
        // so the same robot always yields the same identity string. The simulated daemon
        // returns null values here, which the generated [String: String] map rejects —
        // treat that as "no hardware id" rather than a failed handshake.
        let hardwareMap = try? await client.getRobotHardwareIdApiDaemonHardwareIdGet()
            .ok.body.json.additionalProperties
        let hardwareID = hardwareMap.flatMap { map -> String? in
            map.isEmpty ? nil : map
                .sorted { $0.key < $1.key }
                .map { "\($0.key)=\($0.value)" }
                .joined(separator: ";")
        }

        let name = try? await client.getRobotDisplayNameApiDaemonRobotNameGet().ok.body.json.name

        return Handshake(
            identity: RobotIdentity(
                hardwareID: hardwareID,
                name: name ?? status.robotName,
                daemonVersion: status.version
            ),
            status: status,
            compatibility: compatibility
        )
    }

    /// One-shot full state via REST — fallback only; prefer `StateStreamClient`.
    public func fullState() async throws -> Components.Schemas.FullState {
        try await client.getFullStateApiStateFullGet().ok.body.json
    }

    public func daemonStatus() async throws -> Components.Schemas.DaemonStatus {
        try await client.getDaemonStatusApiDaemonStatusGet().ok.body.json
    }

    public func wakeUp() async throws {
        _ = try await client.playWakeUpApiMovePlayWakeUpPost().ok
    }

    public func gotoSleep() async throws {
        _ = try await client.playGotoSleepApiMovePlayGotoSleepPost().ok
    }

    // MARK: Recorded moves (dances / emotions / music libraries)

    /// Move names available in a HF dataset, e.g. `pollen-robotics/reachy-mini-dances-library`.
    public func listMoves(dataset: String) async throws -> [String] {
        try await client.listRecordedMoveDatasetApiMoveRecordedMoveDatasetsListDatasetNameGet(
            path: .init(datasetName: dataset)
        ).ok.body.json
    }

    /// Starts a recorded move; returns its UUID for `stopMove`.
    public func playMove(dataset: String, move: String) async throws -> String {
        try await client.playRecordedMoveDatasetApiMovePlayRecordedMoveDatasetDatasetNameMoveNamePost(
            path: .init(datasetName: dataset, moveName: move)
        ).ok.body.json.uuid
    }

    /// Authoritative daemon view of tasks still running, used to detect natural completion.
    public func runningMoveUUIDs() async throws -> Set<String> {
        let moves = try await client.getRunningMovesApiMoveRunningGet().ok.body.json
        return Set(moves.map(\.uuid))
    }

    public func stopMove(uuid: String) async throws {
        _ = try await client.stopMoveApiMoveStopPost(body: .json(.init(uuid: uuid))).ok
    }

    /// Recorded music is owned by the daemon's media player, separately from the move task.
    public func stopSound() async throws {
        _ = try await client.stopSoundApiMediaStopSoundPost().ok
    }

    /// Re-acquires camera/audio hardware for the daemon's WebRTC producer.
    /// The simulator registers no producer until this is called; on a real
    /// robot it's a harmless no-op when media is already held.
    public func acquireMedia() async throws {
        _ = try await client.acquireMediaApiMediaAcquirePost().ok
    }
}

