4	/// Connected-robot screen: identity, live daemon status, wake/sleep.
5	struct RobotScreen: View {
6	    let session: RobotSession
7	
8	    var body: some View {
9	        NavigationStack {
10	            content
11	        }
12	    }
13	
14	    private var content: some View {
15	        Form {
16	            statusSection
17	            controlSection
18	            if let warning = session.compatibilityWarning {
19	                Section {
20	                    Label(warning, systemImage: "exclamationmark.triangle")
21	                        .foregroundStyle(.orange)
22	                }
23	            }
24	            if let error = session.lastError {
25	                Section {
26	                    Text(error)
27	                        .font(.caption.monospaced())
28	                        .foregroundStyle(.red)
29	                }
30	            }
31	            Section {
32	                Button("Disconnect", role: .destructive) {
33	                    session.disconnect()
34	                }
35	            }
36	        }
37	        .formStyle(.grouped)
38	    }
39	
40	    private var identity: RobotIdentity? {
41	        switch session.phase {
42	        case let .connected(identity), let .unreachable(identity): identity
43	        default: nil
44	        }
45	    }
46	
47	    private var statusSection: some View {
48	        Section("Robot") {
49	            LabeledContent("Name", value: identity?.name ?? "—")
50	            LabeledContent("Daemon", value: identity?.daemonVersion ?? "—")
51	            LabeledContent("Address", value: session.address?.displayString ?? "—")
52	            if let status = session.lastStatus {
53	                LabeledContent("Daemon state", value: String(describing: status.state))
54	            }
55	            HStack {
56	                Text("Link")
57	                Spacer()
58	                if case .unreachable = session.phase {
59	                    Label("Unreachable — reconnecting…", systemImage: "wifi.exclamationmark")
60	                        .foregroundStyle(.orange)
61	                } else {
62	                    Label("Connected", systemImage: "checkmark.circle")
63	                        .foregroundStyle(.green)
64	                }
65	            }
66	        }
67	    }
68	
69	    private var controlSection: some View {
70	        Section("Control") {
71	            if let address = session.address {
72	                NavigationLink {
73	                    ControllerScreen(address: address)
74	                } label: {
75	                    Label("Controller", systemImage: "gamecontroller")
76	                }
77	                NavigationLink {
78	                    MovesScreen(session: session)
79	                } label: {
80	                    Label("Moves & expressions", systemImage: "music.note")
81	                }
82	                NavigationLink {
83	                    LogConsoleScreen(address: address)
84	                } label: {
85	                    Label("Daemon logs", systemImage: "terminal")
86	                }
87	                if session.lastStatus?.wirelessVersion == true || session.lastStatus?.simulationEnabled == true {
88	                    NavigationLink {
89	                        CameraScreen(address: address)
90	                    } label: {
91	                        Label("Camera", systemImage: "video")
92	                    }
93	                }
94	            }
95	            Button {
96	                Task { await session.wake() }
97	            } label: {
98	                Label("Wake up", systemImage: "sun.max")
99	            }
100	            Button {
101	                Task { await session.sleep() }
102	            } label: {
103	                Label("Go to sleep", systemImage: "moon.zzz")
104	            }
105	        }
106	        .disabled(!isConnected)
107	    }
108	
109	    private var isConnected: Bool {
110	        if case .connected = session.phase {
111	            return true
112	        }
113	        return false
114	    }
115	}
