      return true;
    } catch (err) {
      console.error('Go to sleep error:', err);
      setError(err instanceof Error ? err.message : String(err));
      transitionTo.ready();
      return false;
    } finally {
      setTransitioningState(false);
      cleanupWebSocket();
    }
  }, [
    canToggle,
    isSleeping,
    transitionTo,
    playGoToSleepAnimation,
    waitForMoveCompletion,
    disableMotors,
    setTransitioningState,
