      return wakeUp();
    } else {
      return goToSleep();
    }
  }, [isSleeping, wakeUp, goToSleep]);

  return {
    isSleeping: displaySleeping,
    isAwake: displayAwake,
    isTransitioning,
    canToggle,
    error,

    wakeUp,
    goToSleep,
    toggle,
  };
