    func wakeSleep() async {
        let client = MockRobotClient(probes: [])
        let session = makeSession(client: client)
        await session.connect(to: RobotAddress(host: "10.0.0.9"))
        await session.wake()
        await session.sleep()
        #expect(client.wakeCalls == 1)
        #expect(client.sleepCalls == 1)
        session.disconnect()
    }
}

