import Foundation

public enum ReachyKitError: Error, Sendable, Equatable {
    /// The robot address could not be turned into a valid URL (e.g. malformed host).
    case invalidAddress(RobotAddress)
    /// An operation requiring an active daemon connection was requested while disconnected.
    case notConnected
    /// The daemon API is older than the minimum or belongs to another major version.
    case unsupportedDaemonVersion(reported: String, minimum: String)
}

extension ReachyKitError: LocalizedError {
    public var errorDescription: String? {
        switch self {
        case let .invalidAddress(address):
            "Invalid robot address: \(address.host):\(address.port)"
        case .notConnected:
            "Not connected to a robot"
        case let .unsupportedDaemonVersion(reported, minimum):
            "Unsupported daemon \(reported); this app requires daemon \(minimum)"
        }
    }
}

import ProjectDescription

let project = Project(
    name: "ReachyMiniApps",
    packages: [
        // Local ReachyKit SPM package at the repo root
        .package(path: ".."),
    ],
    targets: [
        .target(
            name: "ReachySpike",
            destinations: [.iPhone, .iPad, .mac],
            product: .app,
            bundleId: "com.alexey1312.ReachyMiniSpike",
            deploymentTargets: .multiplatform(iOS: "17.0", macOS: "14.0"),
            infoPlist: .extendingDefault(with: [
                // Phase 0.4 device checks: Local Network permission + Bonjour + ATS
                "NSLocalNetworkUsageDescription": .string(
                    "Discovers and connects to your Reachy Mini robot on the local network."
                ),
                "NSBonjourServices": .array([
                    .string("_reachy-mini._tcp"),
                    .string("_http._tcp"),
                ]),
                "NSAppTransportSecurity": .dictionary([
                    "NSAllowsLocalNetworking": .boolean(true),
                ]),
                // Phase 2 camera: WebRTC mic uplink (client mic → robot speaker)
                "NSMicrophoneUsageDescription": .string(
                    "Talk to people near your Reachy Mini through its speaker."
                ),
                "UILaunchScreen": .dictionary([:]),
            ]),
            sources: ["ReachySpike/Sources/**"],
            dependencies: [
                .package(product: "ReachyKit"),
                .package(product: "ReachyUI"),
            ]
        ),
    ]
)

