8	public final class RobotSession {
9	    public enum ConnectionPhase: Equatable, Sendable {
10	        case idle
11	        case connecting
12	        case connected(RobotIdentity)
13	        case unreachable(RobotIdentity)
14	    }
15	
16	    /// Wake and sleep are long enough — a cold backend start is budgeted at 90 s —
17	    /// that the UI has to show what the robot is doing meanwhile.
18	    public enum PowerTransition: Equatable, Sendable {
19	        case startingBackend
20	        case wakingUp
21	        case goingToSleep
22	    }
23	
24	    public struct MovePlayback: Equatable, Sendable {
25	        public let dataset: String
26	        public let move: String
27	        public let uuid: String
28	    }
29	
30	    public struct Configuration: Sendable {
31	        /// Upstream polls every 3 s (5 s over robot Wi-Fi).
32	        public var pollInterval: Duration = .seconds(3)
33	        /// Consecutive successful probes required to leave `.unreachable`.
34	        public var requiredConsecutiveSuccesses = 2
35	        /// Move task polling is intentionally cheaper than rendering/state streaming.
36	        public var movePollInterval: Duration = .milliseconds(500)
37	        /// Upstream waits this long for a wake/sleep animation before moving on.
38	        public var moveCompletionTimeout: Duration = .seconds(10)
39	        /// Backend startup budget — upstream's `STARTUP.TIMEOUT_NORMAL`.
40	        public var daemonStartTimeout: Duration = .seconds(90)
41	        /// Motors need a moment to hold their pose before the animation starts.
42	        public var motorSettleDelay: Duration = .milliseconds(300)
43	
44	        public init() {}
45	    }
