81	    /// Connects manually by default. Automatic attempts respect a preceding explicit Disconnect.
82	    @discardableResult
83	    public func connect(to address: RobotAddress, automatically: Bool = false) async -> Bool {
84	        guard !automatically || automaticConnectionAllowed else { return false }
85	        if !automatically {
86	            automaticConnectionAllowed = true
87	        }
88	
89	        let attemptID = UUID()
90	        connectionAttemptID = attemptID
91	        resetConnectionState()
92	        self.address = address
93	        phase = .connecting
94	        lastError = nil
95	
96	        do {
97	            let client = try makeClient(address)
98	            let handshake = try await client.handshake()
99	            guard connectionAttemptID == attemptID, !Task.isCancelled else {
100	                if connectionAttemptID == attemptID {
